        .strategy-card {
            background: var(--bg-card);
            border: 1px solid var(--border);
            border-radius: 6px;
            padding: clamp(0.6rem, 1.1vw, 1.1rem) clamp(0.75rem, 1.2vw, 1.2rem);
            display: flex;
            flex-direction: column;
            gap: clamp(0.3rem, 0.5vw, 0.5rem);
            transition: border-color 0.2s;
