        .strategy-card-body strong { color: var(--text-primary); }

        .strategy-card-tag {
            margin-top: auto;
            display: inline-flex;
        }

        /* Wide card spanning 2 cols */
        .strategy-card.wide { grid-column: span 2; }

        /* ===========================================
           KEYBOARD HINT
           =========================================== */
        .keyboard-hint {
            position: fixed;
            bottom: clamp(0.6rem, 1.2vw, 1.2rem);
            right: clamp(0.75rem, 1.5vw, 1.5rem);
