const { chromium } = require('playwright');
const path = require('path');
const http = require('http');
const fs = require('fs');

(async () => {
    // Start tiny HTTP server
    const dir = '/app/output';
    const server = http.createServer((req, res) => {
        const filePath = path.join(dir, req.url === '/' ? '/presentation.html' : req.url);
        fs.readFile(filePath, (err, data) => {
            if (err) { res.writeHead(404); res.end(); return; }
            res.writeHead(200);
            res.end(data);
        });
    });
    await new Promise(r => server.listen(0, '127.0.0.1', r));
    const port = server.address().port;
    const url = `http://127.0.0.1:${port}/presentation.html`;

    const browser = await chromium.launch({ executablePath: process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE_PATH || undefined });
    const page = await browser.newPage();
    await page.setViewportSize({ width: 1920, height: 1080 });
    await page.goto(url, { waitUntil: 'networkidle' });
    await page.waitForTimeout(1000);

    // Count slides
    const slideCount = await page.$$eval('.slide', els => els.length);
    console.error(`Found ${slideCount} slides`);

    const outDir = '/tmp/slide_captures';
    fs.mkdirSync(outDir, { recursive: true });

    for (let i = 0; i < slideCount; i++) {
        // Scroll to exact slide position
        await page.evaluate((idx) => {
            const slides = document.querySelectorAll('.slide');
            if (slides[idx]) {
                slides[idx].scrollIntoView({ behavior: 'instant' });
            }
        }, i);
        await page.waitForTimeout(800); // allow animations
        const idx = String(i + 1).padStart(3, '0');
        await page.screenshot({ path: `${outDir}/slide_${idx}.png` });
        console.error(`  Captured slide ${i+1}`);
    }

    console.log(JSON.stringify({ captured: slideCount, outDir }));
    await browser.close();
    server.close();
})();
EOF
